@Service
public class OrderService {
    private final PaymentProcessor paymentProcessor;
    private final EmailService emailService;

    // Spring calls this constructor, injects dependencies
    public OrderService(PaymentProcessor paymentProcessor, EmailService emailService) {
        this.paymentProcessor = paymentProcessor;
        this.emailService = emailService;
    }

    public void processOrder(Order order) {
        paymentProcessor.charge(order.getAmount());
        emailService.sendConfirmation(order.getCustomerEmail());
    }
}

// Spring Boot main class — IoC container starts here
@SpringBootApplication
public class ShopApplication {
    public static void main(String[] args) {
        var context = SpringApplication.run(ShopApplication.class, args);
        // Spring already created OrderService with its dependencies
        var orderService = context.getBean(OrderService.class);
    }
}
