// Tight coupling — UserService hardcoded to EmailService
class UserServiceTight {
    private EmailService emailService = new EmailService(); // Cannot swap or test

    public void registerUser(String email) {
        emailService.send(email, "Welcome!");
    }
}

// Loose coupling — depends on interface, implementation injected
interface NotificationService {
    void send(String recipient, String message);
}

@Service
class UserService {
    private final NotificationService notificationService;

    // Spring injects any NotificationService implementation
    public UserService(NotificationService notificationService) {
        this.notificationService = notificationService;
    }

    public void registerUser(String email) {
        notificationService.send(email, "Welcome!"); // Works with any implementation
    }
}

@Service
class EmailNotificationService implements NotificationService {
    public void send(String recipient, String message) { /* send email */ }
}
