// Method 1: Stereotype annotations (auto-detected via component scanning)
@Service  // Makes this class a Spring bean
public class OrderService {
    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {  // Spring injects repository
        this.repository = repository;
    }

    public void placeOrder(Order order) {
        repository.save(order);
    }
}

@Repository  // Also a Spring bean, specialized for data access
public class OrderRepository {
    // Spring manages this as a singleton bean
}

// Method 2: Explicit @Bean declaration in configuration class
@Configuration
public class AppConfig {

    @Bean  // Spring calls this method and manages the returned object
    public ObjectMapper jsonMapper() {
        var mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
        return mapper;  // This ObjectMapper instance becomes a Spring bean
    }

    @Bean
    public RestTemplate restTemplate(ObjectMapper mapper) {  // Spring injects the bean above
        return new RestTemplate();
    }
}

// NOT a Spring bean (plain Java object)
public class OrderValidator {
    public boolean validate(Order order) {
        return order.total() > 0;  // Spring doesn't manage this, no DI happens
    }
}
