@Service
public class ReportService {
    private final DataSource dataSource;
    private Connection connection;

    // Step 1: Constructor called (dependency injection happens here)
    public ReportService(DataSource dataSource) {
        this.dataSource = dataSource;
        System.out.println("Constructor: dataSource injected");
    }

    // Step 2: After dependency injection, before bean is used
    @PostConstruct
    public void initialize() throws SQLException {
        // Now dataSource is guaranteed to be non-null
        this.connection = dataSource.getConnection();
        System.out.println("PostConstruct: connection opened");
    }

    public List<Report> generateReports() {
        // Bean is ready — use connection for queries
        return List.of();
    }

    // Step 3: Before container shutdown
    @PreDestroy
    public void cleanup() throws SQLException {
        if (connection != null && !connection.isClosed()) {
            connection.close();
            System.out.println("PreDestroy: connection closed");
        }
    }
}
