// Method 1: Direct injection (simpler, preferred for one-time use)
@Service
public class ReportService {
    private final ApplicationContext context;

    public ReportService(ApplicationContext context) {
        this.context = context;  // Spring injects the container itself
    }

    public void generateDynamicReport(String reportType) {
        // Dynamic bean lookup based on runtime input
        var generator = context.getBean(reportType + "Generator", ReportGenerator.class);
        generator.generate();
    }
}

// Method 2: ApplicationContextAware interface (for framework code)
@Component
public class BeanRegistryService implements ApplicationContextAware {
    private ApplicationContext context;

    @Override
    public void setApplicationContext(ApplicationContext ctx) {
        this.context = ctx;  // Spring calls this during bean initialization
    }

    public List<String> listAllBeans() {
        return List.of(context.getBeanDefinitionNames());
    }
}
